// causa-storage 1.2.0 codec tests (contract/v1.2.0/CONTRACT.md in kemiller2002/causa-data): the 1.2.0 conformance
// fixtures (fixtures/v1.2.0 of kemiller2002/causa-data at d6d6c86, branch claude/indy-init-competition-launch-vtgdcj,
// not yet tagged causa-storage-v1.2.0; embedded as gzip+base64 of the exact bytes) read, round-trip byte for byte and refuse each negative with its codes; a 1.0.0 or 1.1.0
// investigation cannot hold a 1.2.0 event (CAUSA.UNREPRESENTABLE); new investigations are written in 1.2.0.
namespace Causa.Contract.Tests.Storage

open System
open System.IO
open System.IO.Compression
open System.Text
open Xunit
open Causa.Domain
open Causa.Persistence

module V120Fixtures =
    let investigation =
        "c1b7f6e4-bdfb-5e92-9b19-2ad92b5fbb25",
        "",
        "",
        ""
    /// (name, expected primary code, expected domain code or "", gzip+base64 of the negative fixture document)
    let negatives =
        [
          "v110-title-revised", "CAUSA.UNKNOWN_EVENT_TYPE", "", ""
          "mixed-version-1-1-0-1-2-0", "CAUSA.UNSUPPORTED_VERSION", "", ""
          "title-revised-closed", "CAUSA.HISTORY_INADMISSIBLE", "INVESTIGATION.NOT_OPEN", ""
          "unknown-revised-closed", "CAUSA.HISTORY_INADMISSIBLE", "INVESTIGATION.NOT_OPEN", ""
          "unknown-revised-missing", "CAUSA.HISTORY_INADMISSIBLE", "HISTORY.INADMISSIBLE_EVENT", ""
          "unknown-revised-resolved", "CAUSA.HISTORY_INADMISSIBLE", "HISTORY.INADMISSIBLE_EVENT", ""
          "title-revised-in-group", "CAUSA.HISTORY_INADMISSIBLE", "HISTORY.INADMISSIBLE_EVENT", ""
          "title-blank", "CAUSA.SCHEMA_VIOLATION", "", ""
          "question-blank", "CAUSA.SCHEMA_VIOLATION", "", ""
          "title-revised-unknown-field", "CAUSA.SCHEMA_VIOLATION", "", ""
        ]

    let gunzip (b64: string) =
        use input = new MemoryStream(Convert.FromBase64String b64)
        use gz = new GZipStream(input, CompressionMode.Decompress)
        use output = new MemoryStream()
        gz.CopyTo output
        output.ToArray()

    let id, files =
        let (i, m, e, s) = investigation
        i, { Manifest = gunzip m; Events = gunzip e; Snapshot = gunzip s }

    /// A negative fixture's file set (its base64 files).
    let negativeFiles (doc: byte[]) : FileSet =
        let j = Json.parse (Encoding.UTF8.GetString doc) |> Option.get
        let file n = Json.field "files" (Some j) |> fun f -> Json.field n f |> fun x -> Json.field "base64" x |> Json.text |> Option.get |> Convert.FromBase64String
        { Manifest = file "manifest.json"; Events = file "events.ndjson"; Snapshot = file "snapshot.json" }

module V120 =
    open V120Fixtures
    open StorageFixtures

    [<Fact>]
    let FixtureVerifiesAndRoundTripsByteForByte () =
        match Wire.verify id files with
        | Error e -> failwithf "%A" e
        | Ok w ->
            Assert.Equal("1.2.0", w.Version)
            Assert.True(bytesEqual files (Wire.fileSet w.Version id w.Events))
            let types = w.Events |> List.map (fun e -> e.EventType)
            Assert.Contains("InvestigationTitleRevised", types)
            Assert.Contains("UnknownRevised", types)
            for ev in w.Events do
                match DomainWire.ofWire ev |> Result.bind DomainWire.toWire with
                | Ok back -> Assert.Equal(Canonical.serialize (Wire.toJson ev), Canonical.serialize (Wire.toJson back))
                | Error e -> failwithf "v%d: %s" ev.AggregateVersion e
        match StorageCodecs.codec.Verify address at files with
        | Error e -> failwithf "%A" e
        | Ok v ->
            match StorageCodecs.encodeHistory v.Investigation.Id v.History with
            | Ok re -> Assert.True(bytesEqual files re)
            | Error e -> failwith e

    /// The snapshot equals the replay: the kernel's title, problem statement and questions are the stored state's.
    [<Fact>]
    let SnapshotEqualsTheKernelReplay () =
        match Wire.verify id files, StorageCodecs.codec.Verify address at files with
        | Ok w, Ok v ->
            let state = Some w.State
            let i = v.Investigation
            Assert.Equal(Json.field "title" state |> Json.text, Some i.Title.Value)
            Assert.Equal("Nightly export stopped at 02:10​", i.Title.Value)
            let unknowns =
                Json.field "unknowns" state |> Json.items
                |> List.map (fun u -> (Json.field "id" (Some u) |> Json.text |> Option.get), (Json.field "question" (Some u) |> Json.text |> Option.get))
                |> Map.ofList
            for KeyValue(uid, u) in i.Unknowns do
                Assert.Equal(unknowns[Canonical.guidText uid], u.Question.Value)
                Assert.Equal(UnknownState.Identified, u.State)
            Assert.Contains("Why did the nightly export stop at 02:10,\nand why was no alert raised?", unknowns |> Map.toList |> List.map snd)
            let start = i.Timeline |> List.pick (fun e -> match e.Payload with CoreEvent(InvestigationStarted s) -> Some s | _ -> None)
            Assert.Equal("The nightly export stopped at 02:10 and wrote no file.", i.Observations[start.ObservationId].Original.Value)
            // History is append-only: the first title is still the start's.
            Assert.Equal("Nightly export stopped", start.Title.Value)
            Assert.Equal(AggregateVersion 10L, i.Version)
        | e1, e2 -> failwithf "%A %A" e1 e2

    [<Fact>]
    let EveryNegativeIsRefusedWithItsCodes () =
        Assert.Equal(10, negatives.Length)
        for (name, code, domainCode, doc) in negatives do
            match Wire.verify id (negativeFiles (gunzip doc)) with
            | Error r ->
                Assert.True((r.Code = code), sprintf "%s: expected %s, got %s (%s)" name code r.Code r.Detail)
                if domainCode <> "" then Assert.True((r.Detail = domainCode), sprintf "%s: expected %s, got %s" name domainCode r.Detail)
            | Ok _ -> failwithf "%s was accepted" name
            // The codec the application uses refuses it too, so nothing is loaded.
            Assert.True(Result.isError (StorageCodecs.codec.Verify address at (negativeFiles (gunzip doc))), name)

    [<Fact>]
    let OlderInvestigationsCannotHoldA120Event () =
        for version in [ "1.0.0"; "1.1.0" ] do
            let inv = InvestigationId(Guid.NewGuid())
            let start = started inv version
            for event in [ InvestigationTitleRevised { Title = text "Renamed"; Reason = None }
                           UnknownRevised { UnknownId = Guid.NewGuid(); Question = text "Why?" } ] do
                let revision = envelope inv 2L (Guid.NewGuid()) version event
                match StorageCodecs.encodeHistory inv [ start; revision ] with
                | Error e -> Assert.Contains("CAUSA.UNREPRESENTABLE", e)
                | Ok _ -> failwithf "a %s investigation stored a 1.2.0 event" version
            Assert.True(Result.isOk (StorageCodecs.encodeHistory inv [ start ]))

    [<Fact>]
    let A120InvestigationIsWrittenAndReadBack () =
        let inv = InvestigationId(Guid.NewGuid())
        let start = started inv StorageVersion.v120
        let history = [ start; envelope inv 2L (Guid.NewGuid()) StorageVersion.v120 (InvestigationTitleRevised { Title = text " Pump trips at 12:00 "; Reason = Some(text "exact time") }) ]
        match StorageCodecs.codec.EncodeNew inv history with
        | Error e -> failwithf "%A" e
        | Ok fs ->
            Assert.Contains("\"formatVersion\":\"1.2.0\"", Encoding.UTF8.GetString fs.Manifest)
            match StorageCodecs.codec.Verify address at fs with
            | Ok v ->
                Assert.Equal(" Pump trips at 12:00 ", v.Investigation.Title.Value)
                Assert.Equal<EventEnvelope list>(history, v.History)
            | Error e -> failwithf "%A" e

    /// The save path writes a new investigation in 1.2.0: the start decided with no base (owner decision 4).
    [<Fact>]
    let NewInvestigationsAreWrittenIn120 () =
        let inv = InvestigationId(Guid.NewGuid())
        let commandId = Writes.commandIdAt t0 (Array.create 16 7uy)
        let start =
            { CommandId = commandId
              Investigation = inv
              ExpectedVersion = None
              Command = Core(StartInvestigation { Title = text "Pump trips"; ObservationId = Guid.NewGuid(); Original = text "The pump trips at noon." }) }
        let writable = WorkspaceAddress.workingCopy [] "run-1" |> Option.bind Writable.ofAddress |> Option.get
        let session = SaveSession.initialNew writable inv (CommitOid "head") start true
        match Writes.decideUnsaved human None session with
        | Ok events ->
            Assert.NotEmpty events
            for e in events do
                Assert.Equal("1.2.0", e.Provenance.FormatVersion)
                Assert.Equal("1.2.0", e.Provenance.SemanticVersion)
            match Writes.storageEncoder human (fun _ -> None) session with
            | Ok fs -> Assert.Contains("\"schemaVersion\":\"1.2.0\"", Encoding.UTF8.GetString fs.Manifest)
            | Error e -> failwith e
        | Error e -> failwith e
        Assert.Equal<string list>([ "1.0.0"; "1.1.0"; "1.2.0" ], Wire.supportedVersions)
